DROP TABLE IF EXISTS `national_standard_basic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `national_standard_basic` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `std_code` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '国标号',
  `std_name` text COLLATE utf8mb4_unicode_ci COMMENT '标准名称',
  `std_status` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准状态（Excel 原文）',
  `publish_date` date DEFAULT NULL COMMENT '发布日期',
  `effective_date` date DEFAULT NULL COMMENT '实施日期',
  `abolition_date` date DEFAULT NULL COMMENT '废止日期',
  `std_category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准类别',
  `replaces_std_code` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '代替标准',
  `replace_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代替类型：-1无；0未知；1完全替代；2部分替代',
  `food_standard_mark` int DEFAULT NULL,
  `ccs_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '中国标准分类号',
  `ics_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国际标准分类号',
  `ped_id` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '谱系号（可能多条，英文逗号拼接）',
  `detail_url` text COLLATE utf8mb4_unicode_ci COMMENT '详情链接',
  `std_file_path` text COLLATE utf8mb4_unicode_ci COMMENT '国标文件保存路径',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_national_standard_basic_std_code` (`std_code`)
) ENGINE=InnoDB AUTO_INCREMENT=80128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国标基础信息主表';
/*!40101 SET character_set_client = @saved_cs_client */;

